package service

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/yogaagungk/payload/internal/domain"
)

// DockerfileMarker identifies files generated by payload.
const DockerfileMarker = "# Generated by payload"

// Dockerfile renders a multi-stage Dockerfile for the stack. The app listens
// on the container port derived from the stack.
func Dockerfile(opts domain.ProjectOptions) (string, error) {
	containerPort := opts.Stack.ContainerPort(opts.Port)
	var content string

	switch opts.Stack {
	case domain.StackGo:
		content = fmt.Sprintf(`%s (go stack).
FROM golang:1.27-alpine AS build
WORKDIR /src
COPY go.* ./
RUN go mod download
COPY . .
RUN CGO_ENABLED=0 GOOS=linux go build -trimpath -o /out/app ./...

FROM gcr.io/distroless/static-debian12:nonroot
WORKDIR /app
COPY --from=build /out/app /app/app
EXPOSE %d
USER nonroot:nonroot
ENTRYPOINT ["/app/app"]
`, DockerfileMarker, containerPort)

	case domain.StackNode:
		content = fmt.Sprintf(`%s (node stack). Expects a package.json start script.
FROM node:22-alpine
WORKDIR /app
COPY package*.json ./
RUN if [ -f package-lock.json ]; then npm ci --omit=dev; else npm install --omit=dev; fi
COPY . .
ENV NODE_ENV=production
ENV PORT=%d
EXPOSE %d
CMD ["npm", "start"]
`, DockerfileMarker, containerPort, containerPort)

	case domain.StackPython:
		content = fmt.Sprintf(`%s (python stack). Expects main.py or adjust CMD.
FROM python:3.12-slim
WORKDIR /app
COPY requirements.txt* ./
RUN if [ -f requirements.txt ]; then pip install --no-cache-dir -r requirements.txt; fi
COPY . .
ENV PORT=%d
EXPOSE %d
CMD ["python", "main.py"]
`, DockerfileMarker, containerPort, containerPort)

	case domain.StackStatic:
		content = fmt.Sprintf(`%s (static stack).
FROM nginx:1.27-alpine
COPY . /usr/share/nginx/html
EXPOSE %d
`, DockerfileMarker, containerPort)

	default:
		return "", fmt.Errorf("unsupported stack %q", opts.Stack)
	}
	return content, nil
}

// EnsureDockerfile writes a Dockerfile only when none exists, so re-running
// init never overwrites user edits.
func EnsureDockerfile(dir string, opts domain.ProjectOptions) (path string, created bool, err error) {
	path = filepath.Join(dir, "Dockerfile")
	if _, statErr := os.Stat(path); statErr == nil {
		return path, false, nil
	} else if !os.IsNotExist(statErr) {
		return "", false, fmt.Errorf("inspect Dockerfile: %w", statErr)
	}

	content, err := Dockerfile(opts)
	if err != nil {
		return "", false, err
	}
	if err := writeFileAtomic(path, []byte(content), 0o644); err != nil {
		return "", false, err
	}
	return path, true, nil
}

func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o750); err != nil {
		return fmt.Errorf("create %s: %w", dir, err)
	}
	temp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return fmt.Errorf("create temp file: %w", err)
	}
	name := temp.Name()
	cleanup := func() {
		_ = temp.Close()
		_ = os.Remove(name)
	}
	if err := temp.Chmod(mode); err != nil {
		cleanup()
		return fmt.Errorf("set mode: %w", err)
	}
	if _, err := temp.Write(data); err != nil {
		cleanup()
		return fmt.Errorf("write: %w", err)
	}
	if err := temp.Sync(); err != nil {
		cleanup()
		return fmt.Errorf("sync: %w", err)
	}
	if err := temp.Close(); err != nil {
		_ = os.Remove(name)
		return fmt.Errorf("close: %w", err)
	}
	if err := os.Rename(name, path); err != nil {
		_ = os.Remove(name)
		return fmt.Errorf("install: %w", err)
	}
	return nil
}

// ValidateDockerfileMarker reports whether content was generated by payload.
func ValidateDockerfileMarker(content string) bool {
	return strings.HasPrefix(content, DockerfileMarker)
}
